def diet_plan_score(calories, k, lower, upper):
 window=sum(calories[:k]);score=(window>upper)-(window<lower)
 for i in range(k,len(calories)):
  window+=calories[i]-calories[i-k];score+=(window>upper)-(window<lower)
 return score

